//! Modifier insertion order for `modifier.create`, `physics.*.create` and `sculpt.multires`, checked
//! against the Blender 5.2.2 stack-order oracle (`insertion_cases` in
//! `tests/fixtures/pr18l_stack/expected.json`, generated by `generate.py`).
//!
//! Each oracle case's `steps` are replayed on a box Object through Potter operations: `create` ->
//! `modifier.create`, except physics kinds (`physics.<system>.create` with the kind's
//! `potter_settings`) and multires (`sculpt.multires` with `potter_settings` levels); `pin` ->
//! `modifier.update` with `set.params.use_pin_to_last`. The resulting stack must match the oracle's
//! modifier order and `use_pin_to_last` flags. Each Blender type occurs at most once per case, so the
//! sequence of Potter modifier types identifies the order.

use std::{collections::BTreeMap, error::Error, fmt::Debug, fs, path::PathBuf};

use potter_core::{
    error::PotError,
    model::{Id, SceneDoc},
    ops,
};
use serde_json::{Map, Value, json};

type TestResult<T> = Result<T, Box<dyn Error>>;

const SCENE_ID: &str = "00000000-0000-4000-8000-000000000000";
const OBJECT: &str = "cube";
const HOOK_TARGET: &str = "hook_target";

struct Kind {
    potter_type: String,
    params: Map<String, Value>,
    potter_settings: Map<String, Value>,
}

fn fixture() -> TestResult<Value> {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "tests",
        "fixtures",
        "pr18l_stack",
        "expected.json",
    ]
    .iter()
    .collect();
    Ok(serde_json::from_slice(&fs::read(path)?)?)
}

fn json_str<'a>(value: &'a Value, key: &str) -> TestResult<&'a str> {
    value
        .get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("fixture field `{key}` must be a string").into())
}

fn ensure_eq<T: PartialEq + Debug>(actual: &T, expected: &T, what: &str) -> TestResult<()> {
    if actual == expected {
        Ok(())
    } else {
        Err(format!("{what}: expected {expected:?}, got {actual:?}").into())
    }
}

fn load_kinds(fixture: &Value) -> TestResult<BTreeMap<String, Kind>> {
    let kinds = fixture
        .get("kinds")
        .and_then(Value::as_object)
        .ok_or("fixture kinds must be an object")?;
    let mut parsed = BTreeMap::new();
    for (name, kind) in kinds {
        let params = kind
            .get("params")
            .and_then(Value::as_object)
            .ok_or("fixture kind params must be an object")?
            .clone();
        let potter_settings = kind
            .get("potter_settings")
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default();
        parsed.insert(
            name.clone(),
            Kind {
                potter_type: json_str(kind, "potter_type")?.to_owned(),
                params,
                potter_settings,
            },
        );
    }
    Ok(parsed)
}

fn kind_named<'a>(kinds: &'a BTreeMap<String, Kind>, name: &str) -> TestResult<&'a Kind> {
    kinds
        .get(name)
        .ok_or_else(|| format!("unknown kind `{name}`").into())
}

fn apply_one(doc: &SceneDoc, operation: &Value) -> Result<SceneDoc, PotError> {
    let batch = json!({
        "schema_version": 1,
        "base_revision": doc.revision,
        "operations": [operation],
    });
    Ok(ops::apply_batch(doc, &batch)?.doc)
}

fn pin_flag(params: &Map<String, Value>) -> bool {
    params
        .get("use_pin_to_last")
        .and_then(Value::as_bool)
        .unwrap_or(false)
}

fn create_operation(name: &str, kind: &Kind) -> TestResult<Value> {
    let physics_system = match kind.potter_type.as_str() {
        "cloth" | "soft_body" | "collision" | "dynamic_paint" | "fluid" => {
            Some(kind.potter_type.as_str())
        }
        "particle_system" => Some("particle_emitter"),
        _ => None,
    };
    if let Some(system) = physics_system {
        return Ok(json!({
            "op": format!("physics.{system}.create"),
            "target": {"id": OBJECT},
            "settings": kind.potter_settings,
        }));
    }
    if kind.potter_type == "multires" {
        let levels = kind
            .potter_settings
            .get("levels")
            .cloned()
            .ok_or("multires potter_settings must set levels")?;
        let render_levels = kind
            .potter_settings
            .get("render_levels")
            .cloned()
            .ok_or("multires potter_settings must set render_levels")?;
        return Ok(json!({
            "op": "sculpt.multires",
            "target": {"id": OBJECT},
            "id": name,
            "levels": levels,
            "render_levels": render_levels,
        }));
    }
    Ok(json!({
        "op": "modifier.create",
        "target": {"id": OBJECT},
        "id": name,
        "type": kind.potter_type,
        "params": kind.params,
    }))
}

/// Builds the case's scene through Potter operations. The `hook_target` node is created first so
/// hook modifiers can reference it, as the oracle does.
fn replay(steps: &[Value], kinds: &BTreeMap<String, Kind>) -> TestResult<SceneDoc> {
    let mut doc = apply_one(
        &SceneDoc::new(SCENE_ID.to_owned()),
        &json!({"op": "node.create", "id": OBJECT, "kind": "box", "params": {"size": 2.0}}),
    )?;
    doc = apply_one(
        &doc,
        &json!({"op": "node.create", "id": HOOK_TARGET, "kind": "empty"}),
    )?;
    let mut kind_of: BTreeMap<&str, &Kind> = BTreeMap::new();
    for step in steps {
        match json_str(step, "action")? {
            "create" => {
                let name = json_str(step, "name")?;
                let kind = kind_named(kinds, json_str(step, "kind")?)?;
                kind_of.insert(name, kind);
                doc = apply_one(&doc, &create_operation(name, kind)?)?;
            }
            "pin" => {
                let name = json_str(step, "name")?;
                let kind = *kind_of
                    .get(name)
                    .ok_or_else(|| format!("pin before create for `{name}`"))?;
                let mut params = kind.params.clone();
                params.insert(
                    "use_pin_to_last".to_owned(),
                    step.get("value").cloned().ok_or("pin step needs value")?,
                );
                doc = apply_one(
                    &doc,
                    &json!({
                        "op": "modifier.update",
                        "target": {"id": OBJECT},
                        "id": name,
                        "set": {"params": params},
                    }),
                )?;
            }
            other => return Err(format!("unknown step action `{other}`").into()),
        }
    }
    Ok(doc)
}

/// The cube's stack as `(modifier type, use_pin_to_last)` in evaluation order.
fn stack_summary(doc: &SceneDoc) -> TestResult<Vec<(String, bool)>> {
    let node = doc
        .nodes
        .get(&Id::new(OBJECT)?)
        .ok_or("cube node is missing")?;
    Ok(node
        .modifiers
        .iter()
        .map(|modifier| (modifier.modifier_type.clone(), pin_flag(&modifier.params)))
        .collect())
}

/// The oracle's stack, expressed as Potter modifier types through each entry's create step.
fn expected_summary(
    case: &Value,
    kinds: &BTreeMap<String, Kind>,
) -> TestResult<Vec<(String, bool)>> {
    let steps = case
        .get("steps")
        .and_then(Value::as_array)
        .ok_or("case steps must be an array")?;
    let mut kind_of: BTreeMap<&str, &Kind> = BTreeMap::new();
    for step in steps {
        if step.get("action").and_then(Value::as_str) == Some("create") {
            kind_of.insert(
                json_str(step, "name")?,
                kind_named(kinds, json_str(step, "kind")?)?,
            );
        }
    }
    let names = case
        .get("expected_stack")
        .and_then(Value::as_array)
        .ok_or("case expected_stack must be an array")?
        .iter()
        .map(|name| name.as_str().ok_or("names must be strings"))
        .collect::<Result<Vec<&str>, &str>>()?;
    let pinned = case
        .get("expected_pinned")
        .and_then(Value::as_array)
        .ok_or("case expected_pinned must be an array")?;
    ensure_eq(&pinned.len(), &names.len(), "expected_pinned length")?;
    names
        .iter()
        .zip(pinned)
        .map(|(name, pin)| -> TestResult<(String, bool)> {
            let kind = kind_of
                .get(name)
                .ok_or_else(|| format!("expected stack entry `{name}` has no create step"))?;
            let pinned = pin
                .as_bool()
                .ok_or("expected_pinned entries must be booleans")?;
            Ok((kind.potter_type.clone(), pinned))
        })
        .collect()
}

fn check_insertion_case(case: &Value, kinds: &BTreeMap<String, Kind>) -> TestResult<()> {
    let steps = case
        .get("steps")
        .and_then(Value::as_array)
        .ok_or("case steps must be an array")?;
    let doc = replay(steps, kinds)?;
    ensure_eq(
        &stack_summary(&doc)?,
        &expected_summary(case, kinds)?,
        "stack (modifier type, use_pin_to_last)",
    )
}

#[test]
fn blender_insertion_order_matches_potter_creation_paths() -> TestResult<()> {
    let fixture = fixture()?;
    let kinds = load_kinds(&fixture)?;
    let cases = fixture
        .get("insertion_cases")
        .and_then(Value::as_object)
        .ok_or("fixture insertion_cases must be an object")?;
    assert!(!cases.is_empty(), "fixture has no insertion cases");
    let mut failures = Vec::new();
    for (name, case) in cases {
        if let Err(error) = check_insertion_case(case, &kinds) {
            failures.push(format!("{name}: {error}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    Ok(())
}

#[test]
fn rigid_body_create_leaves_modifier_stack_unchanged() -> TestResult<()> {
    let fixture = fixture()?;
    let kinds = load_kinds(&fixture)?;
    let steps = json!([
        {"action": "create", "name": "array", "kind": "array"},
        {"action": "pin", "name": "array", "value": true},
    ]);
    let mut doc = replay(steps.as_array().ok_or("steps must be an array")?, &kinds)?;
    doc = apply_one(
        &doc,
        &json!({
            "op": "physics.rigid_body.create",
            "target": {"id": OBJECT},
            "type": "active",
            "mass": 1.0,
        }),
    )?;
    ensure_eq(
        &stack_summary(&doc)?,
        &vec![("array".to_owned(), true)],
        "rigid body stack",
    )?;
    let node = doc
        .nodes
        .get(&Id::new(OBJECT)?)
        .ok_or("cube node is missing")?;
    ensure_eq(&node.rigid_body.is_some(), &true, "rigid body was created")
}
